SELECT 
FROM user_coupon uc
INNER JOIN mall_coupon c ON c.id = uc.coupon_id
WHERE uc.user_id = #{userId}
  AND uc.coupon_id = #{couponId}
LIMIT 1

mapper.update:
UPDATE mall_coupon
SET received_quantity = received_quantity + 1,
    updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{couponId}
  AND status = 1
  AND start_at <= #{now}
  AND end_at >= #{now}
  AND received_quantity < total_quantity

UPDATE user_coupon uc
INNER JOIN mall_coupon c ON c.id = uc.coupon_id
SET uc.status = 3
WHERE uc.user_id = #{userId}
  AND uc.status = 1
  AND c.end_at < #{now}

mapper.select:
SELECT 
FROM user_coupon uc
INNER JOIN mall_coupon c ON c.id = uc.coupon_id
WHERE uc.user_id = #{userId}

    AND uc.status = #{status}

ORDER BY uc.status ASC, c.end_at ASC, uc.received_at DESC

